"""Generate a standalone inspector; never embed original rejected excerpts."""
from __future__ import annotations
from html import escape


def render(compiled: dict, frontier: list[dict]) -> str:
    exclusions = ''.join(f'<tr><th scope="row">{escape(i["id"])}</th><td>{escape(i["reason"].replace("_"," "))}</td></tr>' for i in compiled['excluded'])
    included = ''.join(f'<span class="pill">{escape(eid)}</span>' for eid in compiled['included']) or '<em>No authorized evidence selected</em>'
    data = ''.join(f'<tr><td>{f["budget"]}</td><td>{f["estimated_tokens"]}</td><td>{f["selection_score"]:.1f}</td><td>{escape(", ".join(f["included"]))}</td></tr>' for f in frontier)
    percent = max(0, min(100, round(100 * compiled['estimated_tokens'] / compiled['budget'])))
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Prompt Context Forge · Compilation Inspector</title><style>
:root{{color-scheme:dark}}*{{box-sizing:border-box}}body{{margin:0;background:#130f21;color:#f3efff;font:16px/1.55 system-ui,sans-serif}}main{{max-width:1050px;margin:auto;padding:clamp(20px,5vw,60px)}}.eyebrow{{color:#f4bc88;letter-spacing:.2em;text-transform:uppercase;font-weight:bold;font-size:.77rem}}h1{{font-size:clamp(2rem,5vw,3.6rem);line-height:1.15;margin:10px 0}}h2{{margin-top:36px}}p{{color:#c9bedf;max-width:75ch}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px}}.stat,.panel{{background:#211a34;border:1px solid #4e3b67;border-radius:16px;padding:22px}}.val{{font-size:2rem;font-weight:750;display:block}}.label{{color:#c8bbdd;font-size:.85rem}}.panel{{margin-top:20px}}.bar{{height:24px;background:#413456;border-radius:12px;overflow:hidden}}.fill{{height:100%;width:{percent}%;background:linear-gradient(90deg,#f4bc88,#c99af5)}}.pill{{display:inline-block;background:#412d5b;padding:7px 11px;border:1px solid #806399;border-radius:20px;margin:4px}}table{{width:100%;border-collapse:collapse;text-align:left}}td,th{{padding:10px;border-bottom:1px solid #544366}}.scroll{{overflow:auto}}pre{{white-space:pre-wrap;overflow-wrap:anywhere;background:#100c1b;border:1px solid #5d496d;border-radius:9px;padding:18px;font-size:.84rem;color:#eadcfe}}footer{{margin-top:36px;font-size:.87rem;color:#c4b8d5}}details summary{{cursor:pointer;font-weight:600}}</style></head><body><main>
<div class="eyebrow">Prompt build / trust-boundary inspector</div><h1>Prompt Context Forge</h1><p>A deterministic compiler selects pre-scored, authorized evidence inside a strict estimated token budget. Untrusted evidence remains tagged as data, and simple privacy redaction runs before prompt assembly.</p>
<div class="grid"><div class="stat"><span class="label">Estimated tokens</span><span class="val">{compiled['estimated_tokens']}</span></div><div class="stat"><span class="label">Token budget</span><span class="val">{compiled['budget']}</span></div><div class="stat"><span class="label">Included excerpts</span><span class="val">{len(compiled['included'])} / {compiled['total']}</span></div><div class="stat"><span class="label">Redaction matches</span><span class="val">{compiled['redactions']}</span></div></div>
<section class="panel"><h2>Budget utilization</h2><div class="bar" role="img" aria-label="Approximately {percent}% of estimated token budget used"><div class="fill"></div></div><p>{percent}% used · {compiled['unused_tokens']} estimated tokens remaining</p><h2>Evidence selected</h2>{included}</section>
<section class="panel"><h2>Budget frontier</h2><p>Compare which evidence fits as the estimated budget grows.</p><div class="scroll"><table><thead><tr><th>Budget</th><th>Used</th><th>Value</th><th>Selected IDs</th></tr></thead><tbody>{data}</tbody></table></div></section>
<section class="panel"><h2>Excluded sources</h2><div class="scroll"><table><thead><tr><th>Excerpt</th><th>Reason</th></tr></thead><tbody>{exclusions or '<tr><td colspan="2">None</td></tr>'}</tbody></table></div></section>
<section class="panel"><details><summary>View compiled (redacted) prompt</summary><pre>{escape(compiled['prompt'])}</pre></details></section>
<footer>Excerpt relevance and confidence are synthetic input scores, not computed embeddings. Regex-based redaction is incomplete; this is not a production DLP control. Token counts approximate, and the offline demonstration makes no LLM calls.</footer></main></body></html>'''
